```
// Unique paths in m x n grid with obstacles (1 = blocked)
int dp[m][n];
dp[0][0] = grid[0][0] == 0 ? 1 : 0;
for (i = 0; i < m; i++)
  for (j = 0; j < n; j++) {
    if (grid[i][j] == 1) { dp[i][j] = 0; continue; }
    if (i == 0 && j == 0) continue;
    int up   = (i > 0) ? dp[i-1][j] : 0;     // bounds check needed
    int left = (j > 0) ? dp[i][j-1] : 0;
    dp[i][j] = up + left;
  }
return dp[m-1][n-1];
```

