vector<int> spiral(vector<vector<int>>& m) {
    vector<int> r; if (m.empty()) return r;
    int top = 0, bot = m.size() - 1, l = 0, rt = m[0].size() - 1;
    while (top <= bot && l <= rt) {
        for (int j = l; j <= rt; j++) r.push_back(m[top][j]); top++;
        for (int i = top; i <= bot; i++) r.push_back(m[i][rt]); rt--;
        if (top <= bot) { for (int j = rt; j >= l; j--) r.push_back(m[bot][j]); bot--; }
        if (l <= rt) { for (int i = bot; i >= top; i--) r.push_back(m[i][l]); l++; }
    }
    return r;
}

long long countPairs(vector<int>& a, int k) {
    unordered_map<int, int> seen; long long c = 0;
    for (int x : a) {
        if (seen.count(k - x)) c += seen[k - x];
        seen[x]++;
    }
    return c;
}

vector<int> sieve(int n) {
    vector<bool> comp(n + 1, false); vector<int> pr;
    for (int p = 2; p <= n; p++) {
        if (comp[p]) continue;
        pr.push_back(p);
        for (long long q = 1LL * p * p; q <= n; q += p) comp[q] = true;
    }
    return pr;
}

int majority(vector<int>& a) {
